inputs = ['czxe', 'dz', 'zyg', 'vkcj', 'uwxck']
outputs = ['cizyxe', 'dizy', 'ehg', 'vkcj', 'uwxck']

# Analyze each changed pair
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Let's manually examine what changes
print("\nDetailed analysis:")
for idx, inp, outp in changed_pairs:
    print(f"Example {idx}: '{inp}' -> '{outp}'")
    # Find where they differ
    min_len = min(len(inp), len(outp))
    diff_pos = -1
    for i in range(min_len):
        if inp[i] != outp[i]:
            diff_pos = i
            break
    if diff_pos == -1:
        if len(inp) != len(outp):
            diff_pos = min_len
    print(f"  First difference at position {diff_pos}")
    if diff_pos >= 0 and diff_pos < len(outp):
        print(f"  Character at position {diff_pos} in output: '{outp[diff_pos]}'")
    print()

